package io.github.diodeme.ji.session;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import io.github.diodeme.ji.ai.Content;
import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.session.model.CanonicalSessionState;
import io.github.diodeme.ji.session.tree.SessionDocument;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;

final class SessionDocumentExecutionTest {
    private static final Instant NOW = Instant.parse("2026-09-04T01:00:00Z");

    @Test
    void runTurnAttemptAndRestartRecoveryShareTheCanonicalDocumentRevision() {
        SessionDocument empty = SessionDocument.empty(
                "session-1", new ModelRef("faux", "model"), "workspace", NOW);
        Message prompt = new Message("message-user", Message.Role.USER,
                List.of(new Content.Text("hello")), NOW);

        SessionDocument running = empty.startRun(new SessionDocument.RunStart(
                "run-1", "turn-1", "attempt-1", "message-assistant-1", prompt,
                "record-run-start", "record-attempt-1", NOW));

        assertEquals(1, running.revision());
        assertEquals(running.revision(), running.execution().revision());
        CanonicalSessionState.Run run = running.execution().activeRun().orElseThrow();
        assertEquals("run-1", run.id().value());
        assertEquals(CanonicalSessionState.TurnStatus.MODEL_STREAMING,
                run.turns().getFirst().status());
        assertEquals("attempt-1",
                run.turns().getFirst().attempts().getFirst().id().value());
        assertEquals(List.of(SessionDocument.RecordKind.OPERATION_STARTED,
                        SessionDocument.RecordKind.STEP_ATTEMPT),
                running.records().stream().map(SessionDocument.Record::kind).toList());

        SessionDocument paused = running.pauseAfterRestart();
        assertEquals(2, paused.revision());
        assertEquals(CanonicalSessionState.RunStatus.PAUSED,
                paused.execution().activeRun().orElseThrow().status());

        SessionDocument resumed = paused.resumeRun(
                "attempt-2", "message-assistant-2", "record-attempt-2", NOW.plusSeconds(1));
        CanonicalSessionState.Run resumedRun = resumed.execution().activeRun().orElseThrow();
        assertEquals("run-1", resumedRun.id().value());
        assertEquals(2, resumedRun.turns().getFirst().attempts().size());
        assertEquals(CanonicalSessionState.AttemptOutcome.SUPERSEDED,
                resumedRun.turns().getFirst().attempts().getFirst().outcome().orElseThrow());
        assertTrue(resumed.records().stream()
                .anyMatch(record -> record.id().equals("record-attempt-2")));
        assertEquals(resumed.revision(), resumed.execution().revision());
    }

    @Test
    void terminalRunCommitsAssistantUsageAndOperationOutcomeTogether() {
        SessionDocument running = runningDocument();
        Message assistant = new Message("message-assistant", Message.Role.ASSISTANT,
                List.of(new Content.Text("done")), NOW.plusSeconds(1));

        SessionDocument completed = running.finishRun(new SessionDocument.RunCompletion(
                "run-1", 0, "turn-1", 0, "attempt-1", 0,
                List.of(assistant), new Usage(4, 2, 0, 0, 3),
                CanonicalSessionState.RunOutcome.COMPLETED,
                "record-usage", "record-run-finish", NOW.plusSeconds(1)));

        assertTrue(completed.execution().activeRun().isEmpty());
        CanonicalSessionState.Run run = completed.execution().completedRuns().getFirst();
        assertEquals(CanonicalSessionState.RunOutcome.COMPLETED, run.outcome().orElseThrow());
        assertEquals(CanonicalSessionState.TurnOutcome.COMPLETED,
                run.turns().getFirst().outcome().orElseThrow());
        assertEquals(CanonicalSessionState.AttemptOutcome.SUCCEEDED,
                run.turns().getFirst().attempts().getFirst().outcome().orElseThrow());
        assertEquals(List.of("message-user", "message-assistant"),
                completed.snapshot().transcript().stream().map(Message::id).toList());
        assertEquals(new Usage(4, 2, 0, 0, 3), completed.usage());
        assertEquals(SessionDocument.OperationOutcome.COMPLETED,
                completed.records().getLast().outcome().orElseThrow());
        assertEquals(completed.revision(), completed.execution().revision());
    }

    @Test
    void failedTerminalCommitCanRestoreThePreRunSemanticStateAtANewRevision() {
        SessionDocument baseline = SessionDocument.empty(
                "session-1", new ModelRef("faux", "model"), "workspace", NOW);
        SessionDocument running = runningDocument();

        SessionDocument restored = running.rollbackRun("run-1", baseline);

        assertEquals(2, restored.revision());
        assertEquals(restored.revision(), restored.execution().revision());
        assertTrue(restored.execution().activeRun().isEmpty());
        assertTrue(restored.snapshot().transcript().isEmpty());
        assertTrue(restored.records().isEmpty());
        assertEquals(Usage.ZERO, restored.usage());
    }

    @Test
    void permissionAndToolEffectsAdvanceDurableIdentityBeforeCompletion() {
        SessionDocument waiting = waitingForTool();
        CanonicalSessionState.Run run = waiting.execution().activeRun().orElseThrow();
        CanonicalSessionState.Turn turn = run.turns().getLast();
        CanonicalSessionState.ToolExecution prepared = turn.tools().getFirst();
        CanonicalSessionState.Permission pending = turn.permissions().getFirst();

        SessionDocument allowed = waiting.resolveToolPermission(new SessionDocument.ToolPermissionResolution(
                run.id().value(), run.revision(), turn.id().value(), turn.revision(),
                prepared.id().value(), prepared.revision(), pending.id().value(), pending.revision(),
                CanonicalSessionState.PermissionOutcome.ALLOWED, "record-permission-1", NOW.plusSeconds(2)));
        CanonicalSessionState.Run allowedRun = allowed.execution().activeRun().orElseThrow();
        CanonicalSessionState.Turn allowedTurn = allowedRun.turns().getLast();
        CanonicalSessionState.ToolExecution allowedTool = allowedTurn.tools().getFirst();
        assertEquals(CanonicalSessionState.PermissionOutcome.ALLOWED,
                allowedTurn.permissions().getFirst().outcome().orElseThrow());
        assertEquals(CanonicalSessionState.ToolStatus.PREPARED, allowedTool.status());

        SessionDocument running = allowed.startTool(new SessionDocument.ToolExecutionStart(
                allowedRun.id().value(), allowedRun.revision(), allowedTurn.id().value(), allowedTurn.revision(),
                allowedTool.id().value(), allowedTool.revision(),
                allowedTool.attempts().getLast().id().value(), allowedTool.attempts().getLast().revision(),
                "record-tool-running", NOW.plusSeconds(3)));
        CanonicalSessionState.ToolExecution activeTool = running.execution().activeRun().orElseThrow()
                .turns().getLast().tools().getFirst();
        assertEquals(CanonicalSessionState.ToolStatus.RUNNING, activeTool.status());
        assertEquals(1, activeTool.revision());

        SessionDocument paused = running.pauseAfterRestart();
        assertEquals(CanonicalSessionState.ToolStatus.PAUSED, paused.execution().activeRun().orElseThrow()
                .turns().getLast().tools().getFirst().status());
        assertThrows(IllegalStateException.class, () -> completeTool(running, 0));
        assertThrows(IllegalStateException.class, () -> completeTool(paused, activeTool.revision()));
    }

    @Test
    void recoveryDistinguishesPreparedFromAlreadyStartedNonRetryableTools() {
        SessionDocument prepared = waitingForTool(
                CanonicalSessionState.ToolRetryContract.NON_RETRYABLE, false).pauseAfterRestart();
        SessionDocument resumed = prepared.resumeToolBatch(List.of(
                new SessionDocument.ToolResumeStart(
                        "tool-1", "tool-attempt-2", "record-tool-attempt-2")), NOW.plusSeconds(3));
        CanonicalSessionState.ToolExecution resumedTool = resumed.execution().activeRun().orElseThrow()
                .turns().getLast().tools().getFirst();
        assertEquals(CanonicalSessionState.ToolStatus.PREPARED, resumedTool.status());
        assertEquals(2, resumedTool.attempts().size());
        assertEquals(CanonicalSessionState.AttemptOutcome.SUPERSEDED,
                resumedTool.attempts().getFirst().outcome().orElseThrow());

        SessionDocument waiting = waitingForTool(
                CanonicalSessionState.ToolRetryContract.NON_RETRYABLE, false);
        CanonicalSessionState.Run run = waiting.execution().activeRun().orElseThrow();
        CanonicalSessionState.Turn turn = run.turns().getLast();
        CanonicalSessionState.ToolExecution tool = turn.tools().getFirst();
        CanonicalSessionState.Attempt attempt = tool.attempts().getLast();
        SessionDocument started = waiting.startTool(new SessionDocument.ToolExecutionStart(
                run.id().value(), run.revision(), turn.id().value(), turn.revision(),
                tool.id().value(), tool.revision(), attempt.id().value(), attempt.revision(),
                "record-tool-started", NOW.plusSeconds(2)));
        SessionDocument pausedStarted = started.pauseAfterRestart();
        assertThrows(IllegalStateException.class, () -> pausedStarted.resumeToolBatch(List.of(
                new SessionDocument.ToolResumeStart(
                        "tool-1", "tool-attempt-2", "record-tool-attempt-2")), NOW.plusSeconds(3)));
    }

    @Test
    void replayRejectsOperationFinishWithoutMatchingOpenIdentity() {
        SessionDocument empty = SessionDocument.empty(
                "session-1", new ModelRef("faux", "model"), "workspace", NOW);

        assertThrows(IllegalArgumentException.class, () -> empty.appendRecord(
                "record-finish", "main", SessionDocument.RecordKind.OPERATION_FINISHED,
                java.util.Optional.of("missing-operation"), java.util.Optional.of(SessionDocument.OperationKind.RUN),
                java.util.Optional.of(SessionDocument.OperationOutcome.FAILED), java.util.Map.of(), NOW));
    }

    @Test
    void compactionPreservesIdentityAcrossRestartAndRebuildsProviderContext() {
        SessionDocument source = completedConversation();
        SessionDocument started = source.startCompaction(new SessionDocument.CompactionStart(
                "compaction-1", "compaction-attempt-1", "compaction-entry-1",
                List.of("message-assistant"), 42, "preserve identifiers",
                SessionDocument.CompactionReason.MANUAL,
                Optional.empty(),
                "record-compaction-start", "record-compaction-attempt-1", NOW.plusSeconds(10)));
        CanonicalSessionState.Compaction operation = started.execution().compactions().getFirst();
        assertEquals(CanonicalSessionState.CompactionStatus.RUNNING, operation.status());

        SessionDocument paused = started.pauseAfterRestart();
        CanonicalSessionState.Compaction pausedOperation = paused.execution().compactions().getFirst();
        assertEquals(CanonicalSessionState.CompactionStatus.PAUSED, pausedOperation.status());
        SessionDocument resumed = paused.resumeCompaction(new SessionDocument.CompactionResume(
                "compaction-1", pausedOperation.revision(), "compaction-attempt-2",
                "compaction-entry-2", "record-compaction-attempt-2", NOW.plusSeconds(11)));
        CanonicalSessionState.Compaction resumedOperation = resumed.execution().compactions().getFirst();
        assertEquals("compaction-1", resumedOperation.id().value());
        assertEquals(2, resumedOperation.attempts().size());
        assertEquals(0, operation.revision());
        assertEquals(2, resumedOperation.revision());
        assertThrows(IllegalStateException.class, () -> paused.completeCompaction(
                completion(operation, "compaction-entry-1")));

        SessionDocument completed = resumed.completeCompaction(
                completion(resumedOperation, "compaction-entry-2"));
        CanonicalSessionState.Compaction terminal = completed.execution().compactions().getFirst();
        assertEquals(CanonicalSessionState.CompactionOutcome.COMPLETED, terminal.outcome().orElseThrow());
        assertEquals(SessionDocument.EntryKind.COMPACTION, completed.entries().getLast().kind());
        assertEquals(List.of("compaction-entry-2-summary", "message-assistant"),
                completed.providerContext().stream().map(Message::id).toList());
        assertEquals(List.of(SessionDocument.OperationOutcome.COMPLETED), completed.records().stream()
                .filter(record -> record.kind() == SessionDocument.RecordKind.OPERATION_FINISHED)
                .filter(record -> record.operationKind().orElse(null) == SessionDocument.OperationKind.COMPACTION)
                .map(record -> record.outcome().orElseThrow()).toList());
    }

    private static SessionDocument.CompactionCompletion completion(
            CanonicalSessionState.Compaction operation, String resultEntryId) {
        CanonicalSessionState.Attempt attempt = operation.attempts().getLast();
        return new SessionDocument.CompactionCompletion(
                operation.id().value(), operation.revision(), attempt.id().value(), attempt.revision(),
                resultEntryId, "summary", List.of("message-assistant"), 42,
                new Usage(3, 1, 0, 0, 2), java.util.Map.of("source", "manual"),
                "record-compaction-usage", "record-compaction-finish", NOW.plusSeconds(12));
    }

    private static SessionDocument completedConversation() {
        Message assistant = new Message("message-assistant", Message.Role.ASSISTANT,
                List.of(new Content.Text("done")), NOW.plusSeconds(1));
        return runningDocument().finishRun(new SessionDocument.RunCompletion(
                "run-1", 0, "turn-1", 0, "attempt-1", 0,
                List.of(assistant), Usage.ZERO, CanonicalSessionState.RunOutcome.COMPLETED,
                "record-run-usage", "record-run-finish", NOW.plusSeconds(1)));
    }

    private static SessionDocument waitingForTool() {
        return waitingForTool(CanonicalSessionState.ToolRetryContract.READ_ONLY, true);
    }

    private static SessionDocument waitingForTool(
            CanonicalSessionState.ToolRetryContract retryContract, boolean withPermission) {
        SessionDocument running = runningDocument();
        Message assistant = new Message("message-assistant", Message.Role.ASSISTANT,
                List.of(new Content.ToolCall("call-1", "echo", java.util.Map.of("value", "hello"))),
                NOW.plusSeconds(1));
        return running.completeAssistantWithTools(new SessionDocument.AssistantCompletion(
                "run-1", 0, "turn-1", 0, "attempt-1", 0, List.of(assistant), Usage.ZERO,
                List.of(new SessionDocument.ToolStart(
                        "tool-1", "tool-attempt-1", "tool-result-1", "call-1", "echo",
                        retryContract, java.util.Optional.empty(),
                        withPermission ? java.util.Optional.of(new SessionDocument.PermissionStart(
                                "permission-1", NOW.plusSeconds(1_800))) : java.util.Optional.empty(),
                        "record-tool-prepared")),
                "record-tool-usage", NOW.plusSeconds(1)));
    }

    private static SessionDocument completeTool(SessionDocument document, long toolRevision) {
        CanonicalSessionState.Run run = document.execution().activeRun().orElseThrow();
        CanonicalSessionState.Turn turn = run.turns().getLast();
        CanonicalSessionState.ToolExecution tool = turn.tools().getFirst();
        CanonicalSessionState.Attempt attempt = tool.attempts().getLast();
        Message result = new Message("tool-result-1", Message.Role.TOOL,
                List.of(new Content.Text("done")), java.util.Optional.of("call-1"), NOW.plusSeconds(4));
        return document.completeToolBatch(new SessionDocument.ToolBatchCompletion(
                run.id().value(), run.revision(), turn.id().value(), turn.revision(),
                List.of(new SessionDocument.ToolResult(tool.id().value(), toolRevision,
                        attempt.id().value(), attempt.revision(), result,
                        CanonicalSessionState.ToolOutcome.SUCCEEDED,
                        java.util.Optional.of(CanonicalSessionState.PermissionOutcome.ALLOWED))),
                NOW.plusSeconds(4)));
    }

    private static SessionDocument runningDocument() {
        Message prompt = new Message("message-user", Message.Role.USER,
                List.of(new Content.Text("hello")), NOW);
        return SessionDocument.empty("session-1", new ModelRef("faux", "model"), "workspace", NOW)
                .startRun(new SessionDocument.RunStart(
                        "run-1", "turn-1", "attempt-1", "message-assistant-1", prompt,
                        "record-run-start", "record-attempt-1", NOW));
    }
}
